for m in range(M):
    for i in range(I):
        model.addConstr(Storage[m][i] <= StorageSize, name=f"StorageLimit_{m}_{i}")

for m in range(M):
    model.addConstr(gurobipy.quicksum(Hardness[i] * Refine[m][i] for i in range(I)) >= MinHardness * gurobipy.quicksum(Refine[m][i] for i in range(I)), name=f"MinHardness_{m}")
    model.addConstr(gurobipy.quicksum(Hardness[i] * Refine[m][i] for i in range(I)) <= MaxHardness * gurobipy.quicksum(Refine[m][i] for i in range(I)), name=f"MaxHardness_{m}")

for m in range(M):
    for i in range(I):
        model.addConstr(Refine[m][i] >= MinUsage * Use[m][i], name=f"MinUse_{m}_{i}")
        model.addConstr(Refine[m][i] <= StorageSize * Use[m][i], name=f"MaxUse_{m}_{i}")

for m in range(M):
    for i in range(I):
        for j in range(I):
            if Dependencies[i][j] == 1:
                model.addConstr(Use[m][i] <= Use[m][j], name=f"Dep_{m}_{i}_{j}")

for m in range(M):
    for i in range(I):
        if m == 0:
            model.addConstr(Storage[m][i] == InitialAmount + Buy[m][i] - Refine[m][i], name=f"Balance_{m}_{i}")
        else:
            model.addConstr(Storage[m][i] == Storage[m-1][i] + Buy[m][i] - Refine[m][i], name=f"Balance_{m}_{i}")

for m in range(M):
    for i in range(I):
        model.addConstr(Buy[m][i] >= 0, name=f"NonNegBuy_{m}_{i}")
        model.addConstr(Refine[m][i] >= 0, name=f"NonNegRefine_{m}_{i}")
        model.addConstr(Storage[m][i] >= 0, name=f"NonNegStorage_{m}_{i}")
